-- Storyboard pictures, light page colors and added story detail for the published books.
-- Generated; run AFTER the pictures under assets/books/ are live, or readers see broken images.
-- Each statement only touches a page if the page at that position has the expected id, never blanks a book
-- (coalesce), and new pages are inserted last. One transaction: it all applies, or none of it does.
begin;

-- Kiyah's Garden of Tiny Clues
update stories set data = coalesce(jsonb_set(data, '{pages,0,background}', '{"type": "color", "value": "#FFF6E2"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->0->>'id' = 'pg-mig-53';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,1}', (data->'pages'->1->'layers'->1) || '{"src": "/assets/books/kiyah/kiyah-erasing.jpg", "alt": "Kiyah sits alone at a patio table, rubbing out her drawing among crumpled papers, while the flowers sway and a butterfly flutters away"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->1->>'id' = 'pg-mig-56';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"content": "“My picture will never look right,” Kiyah whispered. Every time she started to draw, the flowers swayed and the butterflies flew away."}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->1->>'id' = 'pg-mig-56';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->1->>'id' = 'pg-mig-56';
update stories set data = coalesce(jsonb_set(data, '{pages,1,background}', '{"type": "color", "value": "#F6E5DD"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->1->>'id' = 'pg-mig-56';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers,0}', (data->'pages'->2->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->2->>'id' = 'pg-mig-58' and data::text not like '%ly-kiyah-bench%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers}', (data->'pages'->2->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-kiyah-bench", "alt": "Kiyah frowns at her messy drawing on a garden bench while bees and butterflies flit around her, and Chike walks over to see what she is making", "fit": "cover", "src": "/assets/books/kiyah/stuck-on-the-bench.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-drawing-nobody-understood' and data->'pages'->2->>'id' = 'pg-mig-58' and data::text not like '%ly-kiyah-bench%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,background}', '{"type": "color", "value": "#F3EADF"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->2->>'id' = 'pg-mig-58';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,1}', (data->'pages'->3->'layers'->1) || '{"src": "/assets/books/kiyah/chike-magnifying-glass.jpg", "alt": "Chike crouches by the flowers holding a magnifying glass to his eye while Kiyah watches, curious, hugging her drawing pad"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->3->>'id' = 'pg-mig-61';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,0}', (data->'pages'->3->'layers'->0) || '{"content": "“Maybe the garden is giving you clues,” Chike said, holding up his magnifying glass. “Let’s look really, really close.”"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->3->>'id' = 'pg-mig-61';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,0}', (data->'pages'->3->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->3->>'id' = 'pg-mig-61';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,1}', (data->'pages'->3->'layers'->1) || '{"y": 50}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->3->>'id' = 'pg-mig-61';
update stories set data = coalesce(jsonb_set(data, '{pages,3,background}', '{"type": "color", "value": "#F3EBE0"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->3->>'id' = 'pg-mig-61';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->4->>'id' = 'pg-mig-63' and data::text not like '%ly-kiyah-clues%';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers}', (data->'pages'->4->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-kiyah-clues", "alt": "Kiyah and Chike crouch in the flower bed looking closely at a fuzzy bee with yellow pollen, a leaf with tiny holes and a shining spider web, while Kiyah sketches one clue", "fit": "cover", "src": "/assets/books/kiyah/looking-for-clues.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-drawing-nobody-understood' and data->'pages'->4->>'id' = 'pg-mig-63' and data::text not like '%ly-kiyah-clues%';
update stories set data = coalesce(jsonb_set(data, '{pages,4,background}', '{"type": "color", "value": "#F5EEDE"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->4->>'id' = 'pg-mig-63';
update stories set data = coalesce(jsonb_set(data, '{pages,5,background}', '{"type": "color", "value": "#F4ECDF"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->5->>'id' = 'pg-mig-65';
update stories set data = coalesce(jsonb_set(data, '{pages,6,background}', '{"type": "color", "value": "#F4ECDF"}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->6->>'id' = 'pg-mig-68';
update stories set data = coalesce(jsonb_set(data, '{pages,6,layers,1}', (data->'pages'->6->'layers'->1) || '{"color": ""}'::jsonb), data) where id = 'story-drawing-nobody-understood' and data->'pages'->6->>'id' = 'pg-mig-68';

-- Zech's Paper Airplane Parade
update stories set data = coalesce(jsonb_set(data, '{pages,0,background}', '{"type": "color", "value": "#FFF6E2"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->0->>'id' = 'pg-mig-19';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,1}', (data->'pages'->1->'layers'->1) || '{"src": "/assets/books/airplane/fastest-plane.jpg", "alt": "In his backyard, Zech proudly holds up a sharp blue paper airplane while Corey folds orange paper at the picnic table"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->1->>'id' = 'pg-mig-22';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"content": "“This is the fastest plane in the neighborhood,” Zech announced. He had folded his blue paper into a sharp, pointy nose, just like a jet."}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->1->>'id' = 'pg-mig-22';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->1->>'id' = 'pg-mig-22';
update stories set data = coalesce(jsonb_set(data, '{pages,1,background}', '{"type": "color", "value": "#F4EADF"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->1->>'id' = 'pg-mig-22';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers,0}', (data->'pages'->2->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->2->>'id' = 'pg-mig-24' and data::text not like '%ly-air-first-flights%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers}', (data->'pages'->2->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-air-first-flights", "alt": "On top of the hill, Zech''s blue plane spins into a bush and Corey''s orange plane dips into the grass as the boys watch, surprised", "fit": "cover", "src": "/assets/books/airplane/first-flights.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-fold-that-would-not' and data->'pages'->2->>'id' = 'pg-mig-24' and data::text not like '%ly-air-first-flights%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,background}', '{"type": "color", "value": "#D9EBFA"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->2->>'id' = 'pg-mig-24';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,1}', (data->'pages'->3->'layers'->1) || '{"src": "/assets/books/airplane/comparing-planes.jpg", "alt": "Zech and Corey sit in the grass on the hill, each studying his own bent paper airplane"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->3->>'id' = 'pg-mig-27';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,0}', (data->'pages'->3->'layers'->0) || '{"content": "“Mine needs to go faster,” Zech said. “Mine needs to stay up longer,” Corey said. They sat in the grass and studied their bent planes."}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->3->>'id' = 'pg-mig-27';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,0}', (data->'pages'->3->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->3->>'id' = 'pg-mig-27';
update stories set data = coalesce(jsonb_set(data, '{pages,3,background}', '{"type": "color", "value": "#D9EDFA"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->3->>'id' = 'pg-mig-27';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"content": "“What if we try one of your sharp folds and one of my wide wings?” Corey asked. Zech’s eyes lit up, and he grabbed a fresh sheet of paper. “Let’s build it together!”"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->4->>'id' = 'pg-mig-29';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->4->>'id' = 'pg-mig-29' and data::text not like '%ly-air-combining%';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers}', (data->'pages'->4->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-air-combining", "alt": "On a picnic blanket, Corey holds his wide orange wing next to the pointed nose of Zech''s blue plane while Zech reaches for a fresh sheet of paper", "fit": "cover", "src": "/assets/books/airplane/combining-planes.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-fold-that-would-not' and data->'pages'->4->>'id' = 'pg-mig-29' and data::text not like '%ly-air-combining%';
update stories set data = coalesce(jsonb_set(data, '{pages,4,background}', '{"type": "color", "value": "#F7E9DB"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->4->>'id' = 'pg-mig-29';
update stories set data = coalesce(jsonb_set(data, '{pages,5,background}', '{"type": "color", "value": "#F5F5DE"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->5->>'id' = 'pg-mig-31';
update stories set data = coalesce(jsonb_set(data, '{pages,6,background}', '{"type": "color", "value": "#F5F5DE"}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->6->>'id' = 'pg-mig-34';
update stories set data = coalesce(jsonb_set(data, '{pages,6,layers,1}', (data->'pages'->6->'layers'->1) || '{"color": ""}'::jsonb), data) where id = 'story-fold-that-would-not' and data->'pages'->6->>'id' = 'pg-mig-34';

-- Chike and his flying box
update stories set data = coalesce(jsonb_set(data, '{pages,0,background}', '{"type": "color", "value": "#FFF6E2"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->0->>'id' = 'pg-mig-2';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,1}', (data->'pages'->1->'layers'->1) || '{"src": "/assets/books/flying-box/chike-finds-the-box.jpg", "alt": "Beside the recycling bins, Chike stands at a big empty cardboard box while a glowing outline of a rocket shimmers around it"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->1->>'id' = 'pg-mig-5';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"content": "“This could be a spaceship,” Chike said. The empty box was almost as tall as he was, and he could already picture it zooming into the sky."}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->1->>'id' = 'pg-mig-5';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->1->>'id' = 'pg-mig-5';
update stories set data = coalesce(jsonb_set(data, '{pages,1,background}', '{"type": "color", "value": "#F6EADC"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->1->>'id' = 'pg-mig-5';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers,0}', (data->'pages'->2->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->2->>'id' = 'pg-mig-7' and data::text not like '%ly-box-taping%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers}', (data->'pages'->2->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-box-taping", "alt": "In the backyard, Chike and Mateo tape wide cardboard wings onto the box while Mateo points up at the sky", "fit": "cover", "src": "/assets/books/flying-box/taping-the-wings.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-question-mark' and data->'pages'->2->>'id' = 'pg-mig-7' and data::text not like '%ly-box-taping%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,background}', '{"type": "color", "value": "#F0F4DF"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->2->>'id' = 'pg-mig-7';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,1}', (data->'pages'->3->'layers'->1) || '{"src": "/assets/books/flying-box/first-test-tips-over.jpg", "alt": "The winged box tips over in the grass with its wings folded, and Chike tumbles out laughing while Mateo holds his head in surprise"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->3->>'id' = 'pg-mig-10';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,0}', (data->'pages'->3->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->3->>'id' = 'pg-mig-10';
update stories set data = coalesce(jsonb_set(data, '{pages,3,background}', '{"type": "color", "value": "#F5EDDE"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->3->>'id' = 'pg-mig-10';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"content": "“Our first test taught us something,” Mateo said, holding up a bent wing. “The wings need more support.” Chike nodded. “Then let’s make them stronger.”"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->4->>'id' = 'pg-mig-12';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->4->>'id' = 'pg-mig-12' and data::text not like '%ly-box-support%';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers}', (data->'pages'->4->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-box-support", "alt": "Mateo holds up a floppy cardboard wing and points at the bend while Chike thinks, with tape and cardboard strips beside them", "fit": "cover", "src": "/assets/books/flying-box/wings-need-support.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-question-mark' and data->'pages'->4->>'id' = 'pg-mig-12' and data::text not like '%ly-box-support%';
update stories set data = coalesce(jsonb_set(data, '{pages,4,background}', '{"type": "color", "value": "#F0F5DE"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->4->>'id' = 'pg-mig-12';
update stories set data = coalesce(jsonb_set(data, '{pages,5,background}', '{"type": "color", "value": "#F0F6DC"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->5->>'id' = 'pg-mig-14';
update stories set data = coalesce(jsonb_set(data, '{pages,6,background}', '{"type": "color", "value": "#F0F6DC"}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->6->>'id' = 'pg-mig-17';
update stories set data = coalesce(jsonb_set(data, '{pages,6,layers,1}', (data->'pages'->6->'layers'->1) || '{"color": ""}'::jsonb), data) where id = 'story-question-mark' and data->'pages'->6->>'id' = 'pg-mig-17';

-- Averi's Brave First Step
update stories set data = coalesce(jsonb_set(data, '{pages,0,background}', '{"type": "color", "value": "#FFF6E2"}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->0->>'id' = 'pg-mig-104';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,1}', (data->'pages'->1->'layers'->1) || '{"src": "/assets/books/averi/what-if-i-forget.jpg", "alt": "Averi sits worried on her front steps, hugging her knees, with a thought cloud of a big school stage above her"}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->1->>'id' = 'pg-mig-107';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"content": "“What if I forget?” Averi asked, imagining the big school stage. Her dance was only three days away, and her tummy felt full of butterflies."}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->1->>'id' = 'pg-mig-107';
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->1->>'id' = 'pg-mig-107';
update stories set data = coalesce(jsonb_set(data, '{pages,1,background}', '{"type": "color", "value": "#F5F1DD"}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->1->>'id' = 'pg-mig-107';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers,0}', (data->'pages'->2->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->2->>'id' = 'pg-mig-109' and data::text not like '%ly-averi-notebook%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers}', (data->'pages'->2->'layers') || jsonb_build_array('{"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-averi-notebook", "alt": "Under a shady tree, Yuna shows Averi a notebook drawing of three dots joined by a curving line, and Averi starts to brighten", "fit": "cover", "src": "/assets/books/averi/beginning-middle-end.jpg", "type": "image", "locked": false, "placement": "bottom-half"}'::jsonb)), data) where id = 'story-slowest-dancer' and data->'pages'->2->>'id' = 'pg-mig-109' and data::text not like '%ly-averi-notebook%';
update stories set data = coalesce(jsonb_set(data, '{pages,2,background}', '{"type": "color", "value": "#F5F4DD"}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->2->>'id' = 'pg-mig-109';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,1}', (data->'pages'->3->'layers'->1) || '{"src": "/assets/books/averi/three-chalk-stars.jpg", "alt": "On the sidewalk, Yuna chalks the third of three colorful stars while Averi stands on the first with her eyes closed, taking a breath"}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->3->>'id' = 'pg-mig-112';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,0}', (data->'pages'->3->'layers'->0) || '{"y": 8, "h": 38}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->3->>'id' = 'pg-mig-112';
update stories set data = coalesce(jsonb_set(data, '{pages,3,background}', '{"type": "color", "value": "#FAEED9"}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->3->>'id' = 'pg-mig-112';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"content": "On the second star she practiced her trickiest turn. She wobbled the first time, then spun all the way around. On the third, she held her final pose."}'::jsonb), data) where id = 'story-slowest-dancer' and data->'pages'->4->>'id' = 'pg-mig-114';
