update stories set data = coalesce(jsonb_insert(data, '{pages,5}', '{"id": "pg-kiyah-finished-garden", "layers": [{"h": 100, "w": 100, "x": 0, "y": 0, "id": "ly-pg-kiyah-finished-garden", "alt": "At sunset, with fireflies glowing, Kiyah proudly holds up her finished drawing of a bee, a leaf, a ladybug, a spider web and flowers while Chike claps for her", "fit": "cover", "src": "/assets/books/kiyah/finished-garden.jpg", "type": "image", "locked": false, "placement": "full-bg"}], "background": {"type": "color", "value": "#F4ECDF"}}'::jsonb, true), data) where id = 'story-drawing-nobody-understood' and data->'pages'->5->>'id' = 'pg-mig-65' and data::text not like '%pg-kiyah-finished-garden%';
